import React from 'react';

import { Box } from '@mui/material';

import { CustomTabs, CustomTab } from './styled-tab';

import { TabContext } from './main-page';

const NavBar = () => {

  const { currentTab, setCurrentTab } = React.useContext(TabContext);

  const tabs = [
    {
      label: 'about',
      content: <></>,
    },
    {
      label: 'experience',
      content: <></>,
    }, 
    {
      label: 'other',
      content: <></>
    }
  ];

  const handleTabsChange = (_event: React.SyntheticEvent, newCurrentTab: number) => {
    setCurrentTab(newCurrentTab);
  };

    return <Box
      sx={{ display: 'flex', alignContent: 'center', flexGrow: '1', flexDirection: 'row-reverse'}}
    >
      <Box sx={{ display: 'flex', flexDirection: 'column-reverse'}}>
        <Box sx={{ height: 50 }}/>
        <Box sx={{ display: 'flex', alignItems: 'flex-end' }} >
          <CustomTabs value={currentTab} onChange={handleTabsChange}>
            {tabs.map((tab) => <CustomTab label={tab.label} />)}
          </CustomTabs>
          <img src={require(`./imgs/orange.png`)}
            style={{ width: '125px', height: 'auto' }}
            alt='tanya-title'
          />
        </Box>
    </Box>
    </Box>
};

const Header = () => {
    return <Box>
      <Box sx={{ height: 60}} />
      <Box
        sx={{ height: 200, display: 'flex', alignContent: 'space-between'}}
      >
        <Box> 
          <img src={require(`./imgs/tanya-title.png`)}
            style={{ width: '400px', height: 'auto' }}
            alt='tanya-title'
          />
        </Box>
        <NavBar />
      </Box>
    </Box>
}

export default Header;