import React from 'react';

import Header from './header';

import { AboutPage } from './about-page';

import { Container, ThemeProvider, createTheme } from '@mui/material';

const messages = { 
  name: 'tanya',
  mainPageTab: 'about me',
  projectsTab: 'projects',
  otherTab: 'other',
};

interface TabType {
  label: string;
  content: JSX.Element;
}

interface ContextDefaultValue {
  tabs: TabType[]
  currentTab: number;
  setCurrentTab: React.Dispatch<number>;
};

const tabs = [
    {
      label: 'about',
      content: <AboutPage/>,
    },
    {
      label: 'experience',
      content: <></>,
    }, 
    {
      label: 'other',
      content: <></>
    }
  ];


export const TabContext = React.createContext<ContextDefaultValue>({
  tabs,
  currentTab: 0,
  setCurrentTab: () => {},
});

const MainPageImpl = () => {
  const [ currentTab, setCurrentTab ] = React.useState(0);

  const TabContextValue = {
    tabs,
    currentTab,
    setCurrentTab,
  };

  return <TabContext.Provider value={TabContextValue}>
    <Container maxWidth={'lg'}>
      <Header />
      { tabs.map((tab, index) => {
          return <div
            role='tabpanel'
            hidden={currentTab !== index}
            >
            {tab.content}
          </div>  
        })
      }
    </Container>
  </TabContext.Provider>;
};

const theme = createTheme({

})

const MainPage = () => (
  <ThemeProvider theme={theme}>
    <MainPageImpl />
  </ThemeProvider>
)


export default MainPage;